def transform(grid):
    # The solid divider separates two masks. Mark cells where the
    # foreground in the left mask aligns with the hole in the right mask.
    sep = next(c for c in range(len(grid[0]))
               if all(row[c] == grid[0][c] for row in grid))
    left_width = sep
    out = []
    for row in grid:
        left = row[:left_width]
        right = row[sep + 1:sep + 1 + left_width]
        out.append([3 if a == 1 and b == 0 else 0
                    for a, b in zip(left, right)])
    return out
